template <typename UnionPtrType>
WorkItemPtr WorkItem::Clone() const {
  switch (tag_) {
    case Tag::kBackForward:
      return NewBackForward(
          mojo::Clone(data_.back_forward));
    case Tag::kLoad:
      return NewLoad(
          mojo::Clone(data_.load));
    case Tag::kReload:
      return NewReload(
          mojo::Clone(data_.reload));
    case Tag::kLoadingScript:
      return NewLoadingScript(
          mojo::Clone(data_.loading_script));
    case Tag::kNonLoadingScript:
      return NewNonLoadingScript(
          mojo::Clone(data_.non_loading_script));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, WorkItem>::value>::type*>
bool WorkItem::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kBackForward:
      return mojo::Equals(data_.back_forward, other.data_.back_forward);
    case Tag::kLoad:
      return mojo::Equals(data_.load, other.data_.load);
    case Tag::kReload:
      return mojo::Equals(data_.reload, other.data_.reload);
    case Tag::kLoadingScript:
      return mojo::Equals(data_.loading_script, other.data_.loading_script);
    case Tag::kNonLoadingScript:
      return mojo::Equals(data_.non_loading_script, other.data_.non_loading_script);
  }

  return false;
}
